import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    lines = raw_csv.splitlines(keepends=True)
    start = 0
    while start < len(lines):
        line = lines[start].lstrip()
        if not line.strip() or line.startswith("#"):
            start += 1
        else:
            break

    reader = csv.reader(io.StringIO("".join(lines[start:]), newline=""))
    try:
        columns = next(reader)
    except StopIteration:
        return {"columns": [], "rows": []}

    rows = list(reader)
    width = max([len(columns)] + [len(row) for row in rows])

    used = set(columns)
    while len(columns) < width:
        number = len(columns) + 1
        name = "extra_{}".format(number)
        while name in used:
            number += 1
            name = "extra_{}".format(number)
        columns.append(name)
        used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
